#[path = "/workspace/challenge/src/lib.rs"]
mod original;
#[path = "/workspace/submission/src/lib.rs"]
mod repaired;

fn check(a: u64, f: u64) {
    let gross = (a as u128 + f as u128 + 9999) / 10000;
    let debit = a as u128 + gross - gross / 10;
    let mut balances = vec![0, u64::MAX];
    if debit <= u64::MAX as u128 {
        let d = debit as u64;
        balances.push(d);
        if d > 0 { balances.push(d - 1); }
        if d < u64::MAX { balances.push(d + 1); }
